# -*- coding: utf-8 -*-
"""Module 11: Mach tuan tu (chot, flip-flop, mach mot nhip va 555, thanh ghi dich, bo dem, logic kha trinh). KHONG co slide cua giang vien: dung tu Floyd Ch.7 den 10 (PDF tr.388-640).
Tooley 5.6 den 5.8 (monostable, bistable, ho logic) nam trong Module 02. Moi so lieu tinh bang build/numlib/seq.py (doi chieu o build/verify/verify_m11.py)."""
import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', 'numlib'))
from hx import *
import seq as S
QB = 'Q̅'

def fig_(name, lang, alt, cv, ce):
    return f'<figure class="slide-fig"><img class="fig" src="{{R}}assets/figs/m11/{name}_{lang}.png" alt="{alt}" loading="lazy"><figcaption class="srcnote">{cv if lang == "vi" else ce}</figcaption></figure>'

def module(lang):
    L = lang; P = []
    def part(title, bullets, slides): P.append(dict(title=title, bullets=bullets, slides=slides))
    f = lambda n, a, cv, ce: fig_(n, L, a, cv, ce)
    jt = lambda n: ' → '.join(S.johnson(n, k) for k in range(2 * n + 1)); rt = lambda n: ' → '.join(S.ring(n, k) for k in range(n + 1))
    part(tr('Chốt và flip-flop là phần tử nhớ hai trạng thái bền, khác nhau ở cách bắt thời điểm đổi trạng thái', 'Latches and flip-flops are two-state memory elements that differ in how they time a change'),
         [tr('Chốt S-R và chốt D có cổng', 'S-R latch and gated D latch'), tr('Flip-flop D, J-K, T kích sườn', 'Edge-triggered D, J-K and T flip-flops'), tr('Preset, clear và các thông số thời gian', 'Preset, clear and timing parameters')], [
     (('Chốt đổi trạng thái theo mức, flip-flop đổi theo sườn của xung clock', 'A latch changes with a level, a flip-flop with a clock edge',
       '<p>Cả hai là thiết bị <b>lưỡng bền (bistable)</b>: có hai trạng thái bền, SET (Q = 1) và RESET (Q = 0). <b>Chốt</b> phản ứng với ngõ vào của nó (không đồng bộ) hoặc trong lúc ngõ vào cho phép EN còn tích cực; <b>flip-flop kích sườn</b> chỉ lấy ngõ vào tại sườn lên hoặc sườn xuống của xung clock (đồng bộ). Floyd 7-1, 7-2.</p>' + table(['Thiết bị', 'Khi nào đổi trạng thái', 'Ngõ vào điều khiển'], [['Chốt S-R', 'ngay khi S hoặc R đổi (không đồng bộ)', 'S, R'], ['Chốt D có cổng', 'trong lúc EN tích cực', 'D, EN'], ['Flip-flop kích sườn', 'chỉ tại sườn tích cực của clock', 'D hoặc J, K, T, và clock']]),
       '<p>A <b>latch</b> and a <b>flip-flop</b> are both <b>bistable</b> devices: two stable states, SET (Q = 1) and RESET (Q = 0). A latch responds to its inputs (asynchronously) or while its enable EN is active; an <b>edge-triggered flip-flop</b> samples its inputs only at the rising or falling edge of the clock (synchronously). Floyd 7-1, 7-2.</p>' + table(['Device', 'When it changes', 'Control inputs'], [['S-R latch', 'as soon as S or R changes (asynchronous)', 'S, R'], ['Gated D latch', 'while EN is active', 'D, EN'], ['Edge-triggered flip-flop', 'only at the active clock edge', 'D or J, K, T, and the clock']]),
       '<p>Chốt giống công tắc bấm giữ: đèn đổi ngay khi bạn bấm. Flip-flop giống máy ảnh chỉ chụp đúng lúc đèn flash nháy (sườn clock): giữa hai lần chụp, ngõ vào đổi gì cũng không ảnh hưởng.</p>', '<p>A latch is like a push-and-hold switch: the lamp changes the moment you press. A flip-flop is like a camera that fires only when the flash goes off (the clock edge): whatever the inputs do between two shots has no effect.</p>')),
     (('Chốt S-R gồm hai cổng NOR hoặc NAND nối chéo; bật đồng thời cả hai ngõ vào tích cực là trạng thái cấm', 'An S-R latch is two cross-coupled NOR or NAND gates; activating both inputs at once is the forbidden state',
       '<p>Hồi tiếp chéo giữ lại trạng thái: ngõ ra mỗi cổng là một ngõ vào của cổng kia. Với hai cổng NOR ngõ vào tích cực ở mức CAO; với hai cổng NAND ở mức THẤP (Floyd 7-1).</p>' + table(['NOR: S', 'R', 'Q', 'Ý nghĩa'], [['0', '0', 'giữ nguyên', 'nhớ'], ['1', '0', '1', 'SET'], ['0', '1', '0', 'RESET'], ['1', '1', f'Q = {QB} = 0', 'cấm']]) + table(['NAND: S', 'R', 'Q', 'Ý nghĩa'], [['1', '1', 'giữ nguyên', 'nhớ'], ['0', '1', '1', 'SET'], ['1', '0', '0', 'RESET'], ['0', '0', f'Q = {QB} = 1', 'cấm']]),
       '<p>Cross-coupling stores the state: each gate\'s output is an input of the other. With two NOR gates the inputs are active HIGH; with two NAND gates they are active LOW (Floyd 7-1).</p>' + table(['NOR: S', 'R', 'Q', 'Meaning'], [['0', '0', 'no change', 'memory'], ['1', '0', '1', 'SET'], ['0', '1', '0', 'RESET'], ['1', '1', f'Q = {QB} = 0', 'forbidden']]) + table(['NAND: S', 'R', 'Q', 'Meaning'], [['1', '1', 'no change', 'memory'], ['0', '1', '1', 'SET'], ['1', '0', '0', 'RESET'], ['0', '0', f'Q = {QB} = 1', 'forbidden']]),
       '<p>Trạng thái cấm làm cả hai ngõ ra bằng nhau, nghĩa là Q và ' + QB + ' không còn là phần bù của nhau; khi nhả cả hai ngõ vào cùng lúc, kết quả không đoán trước được. Site đã kiểm cả hai bảng bằng cách mô phỏng cổng lặp tới khi ổn định.</p>', '<p>The forbidden state makes both outputs equal, so Q and ' + QB + ' are no longer complements; releasing both inputs together gives an unpredictable result. The site checked both tables by simulating the gates until they settle.</p>')),
     (('Chốt D có cổng cho Q theo D khi EN = 1 và giữ nguyên khi EN = 0', 'A gated D latch makes Q follow D while EN = 1 and holds when EN = 0',
       '<p>Thêm cổng EN vào chốt S-R và nối $S=D$, $R=\\overline{D}$ thì không thể xảy ra trạng thái cấm (Floyd 7-1).</p>' + table(['EN', 'D', 'Q kế tiếp', 'Ý nghĩa'], [['0', 'x', 'Q', 'giữ nguyên'], ['1', '0', '0', 'RESET'], ['1', '1', '1', 'SET']]) + '<p>Chốt D là phần tử nhớ 1 bit đơn giản nhất: ngõ vào dữ liệu D, ngõ vào cho phép EN (còn gọi là chốt cổng, bộ nhớ đệm).</p>',
       '<p>Adding an EN gate to the S-R latch and wiring $S=D$, $R=\\overline{D}$ makes the forbidden state impossible (Floyd 7-1).</p>' + table(['EN', 'D', 'Next Q', 'Meaning'], [['0', 'x', 'Q', 'hold'], ['1', '0', '0', 'RESET'], ['1', '1', '1', 'SET']]) + '<p>The D latch is the simplest 1-bit memory: a data input D and an enable input EN.</p>',
       '<p>Khi EN = 1 chốt "trong suốt": D đổi bao nhiêu lần thì Q đổi theo bấy nhiêu lần. Muốn chốt đúng một giá trị tại một thời điểm phải dùng flip-flop kích sườn.</p>', '<p>While EN = 1 the latch is "transparent": Q follows every change of D. To capture a value at one instant you need an edge-triggered flip-flop.</p>')),
     (('Flip-flop D, J-K và T chỉ đổi trạng thái tại sườn clock; J-K có đủ bốn chế độ', 'D, J-K and T flip-flops change only at a clock edge; the J-K has all four modes',
       '<p>Flip-flop D: $Q^+=D$ tại sườn tích cực. Flip-flop J-K (Floyd 7-2):</p>' + table(['J', 'K', 'Q kế tiếp', 'Chế độ'], [['0', '0', 'Q', 'không đổi'], ['0', '1', '0', 'RESET'], ['1', '0', '1', 'SET'], ['1', '1', QB, 'lật (toggle)']]) + formula('Phương trình đặc trưng', r'Q^{+}=J\overline{Q}+\overline{K}\,Q') + '<p>Flip-flop T lật khi $T=1$: $Q^+=Q\\oplus T$; nối J = K = T là được.</p>',
       '<p>D flip-flop: $Q^+=D$ at the active edge. J-K flip-flop (Floyd 7-2):</p>' + table(['J', 'K', 'Next Q', 'Mode'], [['0', '0', 'Q', 'no change'], ['0', '1', '0', 'RESET'], ['1', '0', '1', 'SET'], ['1', '1', QB, 'toggle']]) + formula('Characteristic equation', r'Q^{+}=J\overline{Q}+\overline{K}\,Q') + '<p>A T flip-flop toggles when $T=1$: $Q^+=Q\\oplus T$; tie J = K = T.</p>',
       '<p>J = K = 1 làm Q đổi ở mọi sườn nên chu kỳ ngõ ra gấp đôi chu kỳ clock: đó là cơ sở của mạch chia tần số và bộ đếm. Site kiểm phương trình đặc trưng khớp bảng J-K cho cả 8 tổ hợp (J, K, Q).</p>', '<p>J = K = 1 flips Q at every edge, so the output period is twice the clock period: the basis of frequency dividers and counters. The site checked that the characteristic equation matches the J-K table for all 8 combinations (J, K, Q).</p>')),
     (('Preset và clear không đồng bộ ghi đè clock; thời gian thiết lập, giữ và trễ lan truyền giới hạn tốc độ', 'Asynchronous preset and clear override the clock; setup time, hold time and propagation delay limit the speed',
       '<ul><li><b>PRE</b> đặt Q = 1 và <b>CLR</b> đặt Q = 0 bất kể clock (trên nhiều IC chúng tích cực mức THẤP).</li><li><b>Thời gian thiết lập $t_s$</b>: ngõ vào phải ổn định trước sườn clock; <b>thời gian giữ $t_h$</b>: phải còn ổn định sau sườn.</li><li><b>Trễ lan truyền</b> $t_{PLH}$, $t_{PHL}$: từ sườn clock tới lúc ngõ ra đổi.</li><li>Còn có tần số clock lớn nhất, độ rộng xung clock tối thiểu và công suất tiêu thụ (Floyd 7-3).</li></ul><p>Ví dụ minh hoạ (số giả định, không phải của IC cụ thể): $t_s=20$ ns và $t_h=5$ ns nghĩa là D không được đổi trong vùng rộng $20+5=25$ ns quanh sườn clock.</p>',
       '<ul><li><b>PRE</b> sets Q = 1 and <b>CLR</b> sets Q = 0 regardless of the clock (active LOW on many ICs).</li><li><b>Set-up time $t_s$</b>: the input must be stable before the clock edge; <b>hold time $t_h$</b>: it must stay stable after the edge.</li><li><b>Propagation delay</b> $t_{PLH}$, $t_{PHL}$: from the clock edge until the output changes.</li><li>Also the maximum clock frequency, the minimum clock pulse width and the power dissipation (Floyd 7-3).</li></ul><p>Illustration (assumed numbers, not a specific IC): $t_s=20$ ns and $t_h=5$ ns mean D must not change within a $20+5=25$ ns window around the clock edge.</p>',
       '<p>Nếu D đổi trong vùng cấm, flip-flop có thể rơi vào trạng thái trung gian không xác định (mất ổn định). Đó là lý do mọi thiết kế đồng bộ phải đảm bảo thiết lập và giữ.</p>', '<p>If D changes inside the forbidden window the flip-flop can fall into an undefined in-between state (metastability). That is why every synchronous design must guarantee set-up and hold.</p>')),
    ])
    part(tr('Flip-flop dùng để chứa, chia tần số và đếm; mạch một nhịp và 555 tạo xung và dao động theo RC', 'Flip-flops store, divide frequency and count; the one-shot and the 555 make pulses and oscillations from RC'),
         [tr('Chứa song song, chia tần số, đếm', 'Parallel storage, frequency division, counting'), tr('Mạch một nhịp 74121', 'The 74121 one-shot'), tr('Bộ định thời 555: một nhịp và dao động', 'The 555 timer: monostable and astable')], [
     (('Flip-flop có ba ứng dụng cốt lõi: chứa dữ liệu song song, chia tần số và đếm', 'Flip-flops have three core uses: parallel data storage, frequency division and counting',
       '<p>(1) <b>Chứa song song</b>: n flip-flop D dùng chung clock chứa n bit. (2) <b>Chia tần số</b>: mỗi flip-flop J-K ở chế độ lật chia đôi tần số. (3) <b>Đếm</b>: n flip-flop đếm tới $2^n$ trạng thái (Floyd 7-4).</p>' + table(['Số FF n', 'Tần số ra', 'Số trạng thái'], [[str(n), f'f / {2 ** n}', str(2 ** n)] for n in range(1, 6)]),
       '<p>(1) <b>Parallel storage</b>: n D flip-flops sharing a clock hold n bits. (2) <b>Frequency division</b>: each J-K flip-flop in toggle mode halves the frequency. (3) <b>Counting</b>: n flip-flops count through $2^n$ states (Floyd 7-4).</p>' + table(['FFs n', 'Output frequency', 'States'], [[str(n), f'f / {2 ** n}', str(2 ** n)] for n in range(1, 6)]),
       '<p>Ví dụ: tinh thể thạch anh 32 768 Hz qua 15 tầng chia đôi cho đúng 1 Hz vì $32\\,768=2^{15}$ (đồng hồ đeo tay).</p>', '<p>Example: a 32,768 Hz crystal through 15 divide-by-2 stages gives exactly 1 Hz because $32{,}768=2^{15}$ (a wristwatch).</p>')),
     (('Mạch một nhịp (one-shot) tạo một xung có độ rộng đặt bởi RC khi được kích', 'A one-shot makes one pulse whose width is set by an RC when triggered',
       '<p>Mạch một nhịp là đa hài <b>đơn ổn (monostable)</b>: một trạng thái bền, kích thì ra xung rộng $t_W$ rồi tự về. Loại <b>không kích lại</b> bỏ qua xung kích mới trong lúc đang định thời; loại <b>kích lại được</b> thì làm lại thời gian (Floyd 7-5).</p>' + formula('74121 (không kích lại)', r't_W=0{,}7\,R\,C_{EXT}', [('R', 'điện trở ngoài hoặc điện trở trong 2 kΩ'), ('C_{EXT}', 'tụ ngoài')]) + '<p>Ví dụ: dùng điện trở trong 2 kΩ và muốn $t_W=10$ μs thì $C=10\\,\\mu s/(0{,}7\\times2000)=7143$ pF.</p>',
       '<p>A one-shot is a <b>monostable</b> multivibrator: one stable state; when triggered it outputs a pulse $t_W$ wide and returns by itself. A <b>nonretriggerable</b> one-shot ignores new triggers while timing; a <b>retriggerable</b> one restarts its timing (Floyd 7-5).</p>' + formula('74121 (nonretriggerable)', r't_W=0.7\,R\,C_{EXT}', [('R', 'external resistor or the internal 2 kΩ'), ('C_{EXT}', 'external capacitor')]) + '<p>Example: with the internal 2 kΩ and a wanted $t_W=10$ μs, $C=10\\,\\mu s/(0.7\\times2000)=7143$ pF.</p>',
       '<p>Chú ý: hệ số 0,7 chính là $\\ln 2\\approx0{,}693$, thời gian để tụ nạp tới nửa mức. Site tính cả hai cách và chúng khớp trong 1 %. Con số 7143 pF trùng với đáp án Floyd 7-11.</p>', '<p>Note: the factor 0.7 is $\\ln 2\\approx0.693$, the time for the capacitor to charge to the halfway level. The site computed both ways and they agree within 1 %. The 7143 pF figure matches Floyd answer 7-11.</p>')),
     (('Bộ định thời 555 làm mạch một nhịp ($t_W=1{,}1RC$) hoặc mạch dao động có chu kỳ làm việc trên 50 %', 'The 555 timer works as a one-shot ($t_W=1.1RC$) or as an oscillator with a duty cycle above 50 %',
       '<p>Một nhịp: $t_W=1{,}1\\,R_1C_1$; ví dụ Floyd: $R_1=2{,}2$ kΩ, $C_1=0{,}01$ μF cho $t_W=24{,}2$ μs. Dao động (astable), tụ nạp qua $R_1+R_2$ và xả qua $R_2$:</p>' + formula('555 dao động', r't_H=0{,}7(R_1+R_2)C_1,\quad t_L=0{,}7R_2C_1,\quad f=\frac{1{,}44}{(R_1+2R_2)C_1},\quad \text{duty}=\frac{R_1+R_2}{R_1+2R_2}') + f('astable_555', 'dạng sóng 555 dao động', 'tự vẽ theo công thức Floyd 7-6; R1 = 1 kΩ, R2 = 2 kΩ, C = 0,1 μF cho T = 0,35 ms', '') ,
       '<p>Monostable: $t_W=1.1\\,R_1C_1$; Floyd\'s example $R_1=2.2$ kΩ, $C_1=0.01$ μF gives $t_W=24.2$ μs. Astable, C charges through $R_1+R_2$ and discharges through $R_2$:</p>' + formula('555 astable', r't_H=0.7(R_1+R_2)C_1,\quad t_L=0.7R_2C_1,\quad f=\frac{1.44}{(R_1+2R_2)C_1},\quad \text{duty}=\frac{R_1+R_2}{R_1+2R_2}') + f('astable_555', '555 astable waveform', '', 'redrawn from the Floyd 7-6 formulas; R1 = 1 kΩ, R2 = 2 kΩ, C = 0.1 μF give T = 0.35 ms'),
       '<p>Duty cycle luôn lớn hơn 50 % vì $R_1+R_2>R_2$. Muốn dưới 50 % mắc diode qua $R_2$ (Floyd Hình 7-59). Với số liệu trên, tần số công thức 1,44 cho 2 880 Hz còn $1/T$ với 0,7 cho 2 857 Hz: sai khác 0,8 % do làm tròn $1/0{,}693\\approx1{,}44$.</p>', '<p>The duty cycle is always above 50 % because $R_1+R_2>R_2$. For below 50 % put a diode across $R_2$ (Floyd Figure 7-59). With these values the 1.44 formula gives 2,880 Hz while $1/T$ with 0.7 gives 2,857 Hz: a 0.8 % difference from rounding $1/0.693\\approx1.44$.')),
    ])
    part(tr('Thanh ghi dịch chuyển bit qua một dãy flip-flop và cho ra bộ đếm vòng, bộ đếm Johnson, đường trễ', 'A shift register moves bits along a chain of flip-flops and gives ring and Johnson counters and delay lines'),
         [tr('Bốn kiểu vào/ra dữ liệu', 'Four data I/O types'), tr('Bộ đếm vòng và Johnson', 'Ring and Johnson counters'), tr('Ứng dụng: trễ, chuyển song song nối tiếp', 'Applications: delay, serial-parallel conversion')], [
     (('Thanh ghi dịch có bốn kiểu vào/ra và nạp song song xong trong một xung, nạp nối tiếp mất n xung', 'A shift register has four I/O types; a parallel load takes one pulse, a serial load takes n',
       '<p>Thanh ghi lưu và dịch chuyển dữ liệu (Floyd 8-1, 8-2). Bốn kiểu: vào nối tiếp/ra nối tiếp (SISO), vào nối tiếp/ra song song (SIPO), vào song song/ra nối tiếp (PISO), vào song song/ra song song (PIPO).</p>' + table(['Kiểu', 'Nhập dữ liệu', 'Lấy dữ liệu ra', 'Dùng làm'], [['SISO', 'n xung', 'n xung', 'đường trễ'], ['SIPO', 'n xung', 'tức thì', 'nối tiếp sang song song'], ['PISO', '1 xung', 'n xung', 'song song sang nối tiếp'], ['PIPO', '1 xung', 'tức thì', 'thanh ghi lưu']]) + '<p>Thời gian nhập nối tiếp $N$ bit là $N\\times T_{clk}=N/f$.</p>',
       '<p>A register stores and moves data (Floyd 8-1, 8-2). Four types: serial in/serial out (SISO), serial in/parallel out (SIPO), parallel in/serial out (PISO), parallel in/parallel out (PIPO).</p>' + table(['Type', 'Data in', 'Data out', 'Used as'], [['SISO', 'n pulses', 'n pulses', 'delay line'], ['SIPO', 'n pulses', 'at once', 'serial to parallel'], ['PISO', '1 pulse', 'n pulses', 'parallel to serial'], ['PIPO', '1 pulse', 'at once', 'storage register']]) + '<p>Entering $N$ bits serially takes $N\\times T_{clk}=N/f$.</p>',
       '<p>Ví dụ Floyd: clock 100 kHz nhập 8 bit mất $8\\times10\\,\\mu s=80\\,\\mu s$. Nhập song song 8 bit chỉ cần một xung, trễ bằng trễ lan truyền của một flip-flop.</p>', '<p>Floyd example: a 100 kHz clock enters 8 bits in $8\\times10\\,\\mu s=80\\,\\mu s$. A parallel entry of 8 bits needs one pulse, and the delay is one flip-flop propagation delay.</p>')),
     (('Nối ngõ ra cuối về ngõ vào cho bộ đếm vòng (modulus n) và nối qua đảo cho bộ đếm Johnson (modulus 2n)', 'Feeding the last output back gives a ring counter (modulus n); feeding it back inverted gives a Johnson counter (modulus 2n)',
       '<p>Hai <b>bộ đếm thanh ghi dịch</b> (Floyd 8-4) có chuỗi trạng thái quy định, bắt đầu từ 1000 (vòng) và 0000 (Johnson), dịch phải:</p>' + table(['Bộ đếm', 'Chuỗi trạng thái (4 flip-flop)', 'Modulus'], [['Vòng', rt(4), '4'], ['Johnson', jt(4), '8']]) + '<p>Bộ đếm Johnson dùng ít flip-flop hơn một nửa so với bộ đếm vòng cùng modulus, và mỗi trạng thái giải mã bằng một cổng AND hai ngõ vào.</p>',
       '<p>Two <b>shift register counters</b> (Floyd 8-4) have specified state sequences, starting at 1000 (ring) and 0000 (Johnson), shifting right:</p>' + table(['Counter', 'State sequence (4 flip-flops)', 'Modulus'], [['Ring', rt(4), '4'], ['Johnson', jt(4), '8']]) + '<p>A Johnson counter needs half as many flip-flops as a ring counter of the same modulus, and each state decodes with a two-input AND gate.</p>',
       '<p>Bộ đếm vòng modulus 8 cần 8 flip-flop, bộ đếm Johnson modulus 8 chỉ cần 4: đúng với đáp án Floyd Self-Test 7, 8 chương 8. Số trạng thái dùng được của Johnson là $2n$ trong tổng $2^n$ có thể.</p>', '<p>A modulus-8 ring counter needs 8 flip-flops, a modulus-8 Johnson counter only 4: matching Floyd Chapter 8 Self-Test 7 and 8. A Johnson counter uses $2n$ of the $2^n$ possible states.</p>')),
     (('Thanh ghi dịch làm đường trễ với trễ $N/f$ và đổi dữ liệu song song thành nối tiếp', 'A shift register makes a delay line with delay $N/f$ and converts parallel data to serial',
       '<p>(Floyd 8-5.) Một thanh ghi SISO $N$ bit trễ tín hiệu đúng $N$ chu kỳ clock. Muốn trễ $t$ thì cần tần số clock $f=N/t$.</p>' + formula('Đường trễ thanh ghi dịch', r'\text{trễ}=\frac{N}{f}\;\Longleftrightarrow\; f=\frac{N}{t}') + '<p>Ví dụ Floyd Self-Test 9: 8 bit, trễ 24 μs cần $f=8/24\\,\\mu s=333$ kHz. Truyền dữ liệu nối tiếp giữa hai máy cũng dùng PISO ở bên gửi và SIPO ở bên nhận (nối tiếp ↔ song song).</p>',
       '<p>(Floyd 8-5.) An $N$-bit SISO register delays a signal by exactly $N$ clock periods. For a delay $t$ the clock must be $f=N/t$.</p>' + formula('Shift-register delay line', r'\text{delay}=\frac{N}{f}\;\Longleftrightarrow\; f=\frac{N}{t}') + '<p>Floyd Self-Test 9: 8 bits and a 24 μs delay need $f=8/24\\,\\mu s=333$ kHz. Serial data links also use a PISO at the sender and a SIPO at the receiver (serial ↔ parallel).</p>',
       '<p>Đây là ý tưởng của đường truyền nối tiếp trên tàu bay (Module 05): cả hai đầu cần clock hoặc tốc độ bit thống nhất. Site tính 333,3 kHz bằng hai cách (chia và nghịch đảo): khớp.</p>', '<p>This is the idea behind aircraft serial links (Module 05): both ends need a common clock or bit rate. The site computed 333.3 kHz two ways (division and reciprocal): they agree.</p>')),
    ])
    part(tr('Bộ đếm là máy trạng thái: gợn sóng thì đơn giản nhưng chậm, đồng bộ thì nhanh nhưng cần logic điều khiển', 'A counter is a state machine: ripple is simple but slow, synchronous is fast but needs control logic'),
         [tr('Máy trạng thái Moore và Mealy', 'Moore and Mealy state machines'), tr('Bộ đếm không đồng bộ (gợn sóng)', 'Asynchronous (ripple) counters'), tr('Bộ đếm đồng bộ và lên/xuống', 'Synchronous and up/down counters'), tr('Bộ đếm cắt cụt, mắc tầng, giải mã', 'Truncated, cascaded and decoded counters')], [
     (('Bộ đếm là máy trạng thái hữu hạn; modulus là số trạng thái thực sự của chuỗi', 'A counter is a finite state machine; the modulus is the actual number of states in its sequence',
       '<p>Máy trạng thái là mạch tuần tự có số trạng thái hữu hạn theo thứ tự quy định (Floyd 9-1). <b>Moore</b>: ngõ ra chỉ phụ thuộc trạng thái hiện tại. <b>Mealy</b>: ngõ ra phụ thuộc trạng thái hiện tại và ngõ vào. Cả hai gồm logic tổ hợp và bộ nhớ (flip-flop), clock không tính là ngõ vào điều khiển.</p>' + table(['', 'Moore', 'Mealy'], [['Ngõ ra phụ thuộc', 'trạng thái hiện tại', 'trạng thái hiện tại và ngõ vào'], ['Ví dụ', 'bộ đếm có modulus cố định', 'đếm 25, 50 hoặc 100 viên (đóng chai) theo ngõ chọn modulus']]),
       '<p>A state machine is a sequential circuit with a finite number of states in a prescribed order (Floyd 9-1). <b>Moore</b>: the outputs depend only on the present state. <b>Mealy</b>: the outputs depend on the present state and on the inputs. Both consist of combinational logic and memory (flip-flops); the clock is not counted as a controlling input.</p>' + table(['', 'Moore', 'Mealy'], [['Outputs depend on', 'present state', 'present state and inputs'], ['Example', 'a counter with a fixed modulus', 'count 25, 50 or 100 tablets (bottling) chosen by modulus-select inputs']]),
       '<p>Chú ý: khoá in của Floyd Self-Test 2 chương 9 ghi "(a) ngõ vào", chỉ một nửa định nghĩa Mealy; site dùng "(d) ngõ vào và trạng thái hiện tại" theo đúng văn bản mục 9-1.</p>', '<p>Note: the printed key of Floyd Chapter 9 Self-Test 2 says "(a) inputs", half of the Mealy definition; the site uses "(d) inputs and the present state", following the text of 9-1.</p>')),
     (('Bộ đếm gợn sóng: mỗi tầng lật khi tầng trước đổi từ 1 xuống 0, nên trễ cộng dồn $n\\times t_{pd}$', 'Ripple counter: each stage toggles when the previous one falls from 1 to 0, so the delay adds up to $n\\times t_{pd}$',
       '<p>Bộ đếm <b>không đồng bộ (gợn sóng)</b> cho flip-flop sau nhận clock từ ngõ ra Q của flip-flop trước (Floyd 9-2). Modulus tối đa $2^n$. Trễ tích luỹ phải nhỏ hơn chu kỳ clock.</p>' + formula('Tần số clock tối đa', r'f_{max}\approx\frac{1}{n\,t_{pd}}') + f('ripple_timing', 'giản đồ thời gian bộ đếm gợn sóng 3 bit', 'tự vẽ lại theo ý Floyd 9-2; trễ lan truyền được bỏ qua', '') + '<p>Ví dụ Floyd Self-Test 10: 4 flip-flop, mỗi cái 12 ns: quay từ 1111 về 0000 mất $4\\times12=48$ ns.</p>',
       '<p>In an <b>asynchronous (ripple)</b> counter each flip-flop takes its clock from the Q output of the previous one (Floyd 9-2). Maximum modulus $2^n$. The cumulative delay must be less than the clock period.</p>' + formula('Maximum clock frequency', r'f_{max}\approx\frac{1}{n\,t_{pd}}') + f('ripple_timing', '3-bit ripple counter timing diagram', '', 'redrawn after the idea of Floyd 9-2; propagation delay is ignored') + '<p>Floyd Self-Test 10: 4 flip-flops of 12 ns each: recycling from 1111 to 0000 takes $4\\times12=48$ ns.</p>',
       '<p>Trong lúc các tầng đang lật nối đuôi nhau, ngõ ra tạm thời cho các mã sai (ví dụ 0111 → 0110 → 0100 → 0000 khi đổi từ 0111 sang 1000 qua các bước trung gian): đó là lý do phải cẩn thận khi giải mã ngõ ra của bộ đếm gợn sóng.</p>', '<p>While the stages flip one after another the outputs briefly show wrong codes (for example the change from 0111 to 1000 passes through intermediate codes): which is why decoding the outputs of a ripple counter needs care.</p>')),
     (('Bộ đếm đồng bộ cho mọi flip-flop dùng chung clock nên nhanh hơn; điều khiển bằng cổng AND vào J và K', 'A synchronous counter clocks every flip-flop together, so it is faster; AND gates on J and K control it',
       '<p>(Floyd 9-3, 9-4, 9-5.) Mọi flip-flop nhận cùng một clock; flip-flop thứ $k$ chỉ lật khi mọi bit thấp hơn bằng 1 (J = K = tích các Q thấp hơn). Bộ đếm lên/xuống đổi chiều bằng một ngõ vào điều khiển UP/DOWN. Thiết kế: sơ đồ trạng thái → bảng trạng thái kế → bảng kích J-K → tối giản bằng K-map → mạch.</p>' + table(['Q → Q kế', 'J', 'K'], [['0 → 0', '0', 'x'], ['0 → 1', '1', 'x'], ['1 → 0', 'x', '1'], ['1 → 1', 'x', '0']]),
       '<p>(Floyd 9-3, 9-4, 9-5.) Every flip-flop receives the same clock; flip-flop $k$ toggles only when all lower bits are 1 (J = K = the product of the lower Q outputs). An up/down counter reverses with an UP/DOWN control input. Design: state diagram → next-state table → J-K excitation table → K-map minimisation → circuit.</p>' + table(['Q → next Q', 'J', 'K'], [['0 → 0', '0', 'x'], ['0 → 1', '1', 'x'], ['1 → 0', 'x', '1'], ['1 → 1', 'x', '0']]),
       '<p>Bảng kích J-K suy ra từ bảng J-K: để đi từ 0 lên 1 cần J = 1 còn K tuỳ ý (đặt hoặc lật đều được), v.v. Site kiểm bảng này bằng chương trình cho cả bốn chuyển trạng thái.</p>', '<p>The J-K excitation table comes from the J-K table: going from 0 to 1 needs J = 1 and any K (set or toggle both work), and so on. The site checked the table by program for all four transitions.</p>')),
     (('Bộ đếm cắt cụt có modulus không phải lũy thừa của 2; mắc tầng thì modulus nhân với nhau', 'A truncated counter has a modulus that is not a power of 2; cascading multiplies the moduli',
       '<p><b>Bộ đếm cắt cụt</b> bỏ bớt trạng thái. Bộ đếm BCD (decade) đếm 0000 đến 1001 (mười trạng thái) và quay về 0000; bộ đếm gợn sóng làm điều này bằng cách giải mã 1010 để reset không đồng bộ (Floyd 9-2). Cần $n=\\lceil\\log_2 N\\rceil$ flip-flop cho modulus $N$. <b>Mắc tầng</b>: modulus tổng là tích, tần số ra là $f/\\prod N_i$ (Floyd 9-6).</p>' + formula('Chia tần số mắc tầng', r'f_{out}=\frac{f_{clk}}{N_1N_2\cdots N_k}') + '<p>Ví dụ Floyd Self-Test 14: 10 MHz với các tầng 5, 8, 10, 10 cho $10\\text{ MHz}/4000=2{,}5$ kHz. Giải mã trạng thái (Floyd 9-7) có thể sinh gai (glitch) ngắn ở bộ đếm gợn sóng.</p>',
       '<p>A <b>truncated counter</b> skips states. A BCD (decade) counter counts 0000 to 1001 (ten states) and returns to 0000; a ripple counter does this by decoding 1010 to reset asynchronously (Floyd 9-2). A modulus $N$ needs $n=\\lceil\\log_2 N\\rceil$ flip-flops. <b>Cascading</b>: the overall modulus is the product and the output frequency is $f/\\prod N_i$ (Floyd 9-6).</p>' + formula('Cascaded frequency division', r'f_{out}=\frac{f_{clk}}{N_1N_2\cdots N_k}') + '<p>Floyd Self-Test 14: 10 MHz with stages 5, 8, 10, 10 gives $10\\text{ MHz}/4000=2.5$ kHz. Decoding states (Floyd 9-7) can produce short glitches in a ripple counter.</p>',
       '<p>Bộ đếm modulus 13 đếm 0 đến 12: nó cần 4 flip-flop vì $2^3=8<13\\le16$, và khởi đầu từ 0000 (Floyd Self-Test 16). Bộ đếm modulus 60 của đồng hồ là chuỗi mod 10 rồi mod 6.</p>', '<p>A modulus-13 counter counts 0 to 12: it needs 4 flip-flops because $2^3=8<13\\le16$, and starts from 0000 (Floyd Self-Test 16). The modulus-60 counter of a clock is a mod-10 followed by a mod-6.</p>')),
    ])
    part(tr('Logic khả trình biến một con chip thành mạch tuỳ ý: từ PAL đơn giản đến CPLD và FPGA, nạp bằng phần mềm', 'Programmable logic turns one chip into any circuit: from the simple PAL to CPLDs and FPGAs, loaded by software'),
         [tr('SPLD: PAL, PLA, GAL', 'SPLD: PAL, PLA, GAL'), tr('CPLD và FPGA', 'CPLD and FPGA'), tr('Luồng thiết kế và quét biên JTAG', 'Design flow and JTAG boundary scan')], [
     (('SPLD thực hiện tổng các tích (SOP): PAL có mảng AND lập trình được và mảng OR cố định', 'An SPLD implements sums of products: a PAL has a programmable AND array and a fixed OR array',
       '<p>(Floyd 10-1.) Mọi hàm Boolean viết được dạng SOP nên chỉ cần mảng AND rồi OR. Ba kiểu SPLD:</p>' + table(['Thiết bị', 'Mảng AND', 'Mảng OR', 'Ghi chú'], [['PAL', 'lập trình được', 'cố định', 'lập trình một lần (cầu chì)'], ['PLA', 'lập trình được', 'lập trình được', 'linh hoạt hơn PAL'], ['GAL', 'lập trình được', 'cố định', 'xoá và lập trình lại được, có macrocell ngõ ra']]) + '<p>Ví dụ: XOR $F=\\overline{A}B+A\\overline{B}$ dùng hai số hạng tích; PAL giữ lại đúng bốn liên kết (hai cho mỗi số hạng) và đốt các cầu chì còn lại.</p>',
       '<p>(Floyd 10-1.) Every Boolean function can be written as SOP, so an AND array followed by an OR is enough. Three kinds of SPLD:</p>' + table(['Device', 'AND array', 'OR array', 'Note'], [['PAL', 'programmable', 'fixed', 'one-time programmable (fuses)'], ['PLA', 'programmable', 'programmable', 'more flexible than a PAL'], ['GAL', 'programmable', 'fixed', 'erasable and reprogrammable, with output macrocells']]) + '<p>Example: the XOR $F=\\overline{A}B+A\\overline{B}$ uses two product terms; the PAL keeps exactly four links (two per term) and blows the other fuses.</p>',
       '<p>Khoá in của Floyd Đúng/Sai 1 chương 10 bắt bẻ đúng điều này: "PAL có mảng OR lập trình được nối với mảng AND cố định" là SAI (ngược lại).</p>', '<p>Floyd Chapter 10 True/False 1 tests exactly this: "a PAL has a programmable OR array and a fixed AND array" is FALSE (it is the other way round).</p>')),
     (('CPLD ghép nhiều khối LAB qua mảng nối PIA; FPGA gồm khối logic CLB và khối I/O với mật độ lớn hơn nhiều', 'A CPLD joins several LABs through the PIA; an FPGA has logic blocks (CLBs) and I/O blocks with a much higher density',
       '<p><b>CPLD</b> (Floyd 10-2, 10-3): nhiều khối <b>LAB</b> (mỗi khối xấp xỉ một SPLD) nối qua <b>PIA</b>; mỗi LAB gồm các <b>macrocell</b>: mảng AND-OR, bộ dồn kênh chọn chế độ (<i>tổ hợp</i> hoặc <i>có thanh ghi</i>) và flip-flop D hoặc J-K lập trình được. Biến thể <b>LUT-CPLD</b> dùng bảng tra thay mảng AND-OR. <b>FPGA</b> (Floyd 10-4): các <b>CLB</b>, khối I/O và đường nối lập trình được; kiểu <b>SRAM</b> mất cấu hình khi tắt nguồn, kiểu <b>antifuse</b> thì không. Khối đơn giản và nhiều thì gọi là <b>hạt mịn</b> (fine grained).</p>',
       '<p><b>CPLD</b> (Floyd 10-2, 10-3): several <b>LABs</b> (each roughly one SPLD) joined by the <b>PIA</b>; each LAB holds <b>macrocells</b>: an AND-OR array, multiplexers that choose the mode (<i>combinational</i> or <i>registered</i>) and a programmable D or J-K flip-flop. The <b>LUT-CPLD</b> variant uses look-up tables instead of an AND-OR array. <b>FPGA</b> (Floyd 10-4): <b>CLBs</b>, I/O blocks and programmable interconnect; an <b>SRAM</b> FPGA loses its configuration when power is removed, an <b>antifuse</b> one does not. Simple, numerous blocks are called <b>fine grained</b>.</p>',
       '<p>Một LUT $n$ ngõ vào lưu $2^n$ bit và thực hiện được $2^{2^n}$ hàm: LUT 4 ngõ vào là 16 bit và 65 536 hàm. Sách ghi mật độ FPGA lớn hơn CPLD; khoá in Đúng/Sai 7 ghi sai "LAB không có trong CPLD" nên site dùng "có".</p>', '<p>An $n$-input LUT stores $2^n$ bits and implements $2^{2^n}$ functions: a 4-input LUT is 16 bits and 65,536 functions. The book says an FPGA is denser than a CPLD; the printed key of True/False 7 wrongly says LABs are not in CPLDs so the site uses "they are".</p>')),
     (('Luồng thiết kế đi từ nhập thiết kế qua tổng hợp, mô phỏng đến nạp; JTAG dùng bốn chân TDI, TDO, TCK, TMS', 'The design flow goes from design entry through synthesis and simulation to downloading; JTAG uses four pins TDI, TDO, TCK, TMS',
       '<p>(Floyd 10-5, 10-6.) <b>Luồng thiết kế (design flow)</b>: nhập thiết kế (sơ đồ nguyên lý hoặc HDL) → tổng hợp ra <b>netlist</b> (định dạng EDIF) → mô phỏng chức năng (người dùng đặt dạng sóng ngõ vào) → đặt và đi dây cho <b>thiết bị đích</b> → mô phỏng thời gian → nạp tệp lập trình. <b>Quét biên (boundary scan, JTAG)</b> kiểm tra mạch in qua cổng truy cập kiểm tra (TAP) với bốn tín hiệu: <b>TDI</b> (dữ liệu vào), <b>TDO</b> (dữ liệu ra), <b>TCK</b> (clock), <b>TMS</b> (chọn chế độ); mô tả bằng ngôn ngữ BSDL.</p>',
       '<p>(Floyd 10-5, 10-6.) The <b>design flow</b>: design entry (schematic or HDL) → synthesis to a <b>netlist</b> (EDIF format) → functional simulation (the user supplies the input waveforms) → place and route for the <b>target device</b> → timing simulation → download of the programming file. <b>Boundary scan (JTAG)</b> tests a board through the test access port (TAP) with four signals: <b>TDI</b> (data in), <b>TDO</b> (data out), <b>TCK</b> (clock), <b>TMS</b> (mode select); it is described in BSDL.</p>',
       '<p>Ngôn ngữ mô tả phần cứng (HDL) là chủ đề của Module 14 (VHDL, Tooley Chương 17). Ở đây chỉ cần nhớ HDL là một trong hai cách nhập thiết kế.</p>', '<p>Hardware description languages (HDL) are the subject of Module 14 (VHDL, Tooley Chapter 17). Here just remember that HDL is one of the two ways of design entry.</p>')),
    ])
    parts = []
    for part_ in P:
        slides = [sl(tr(bv, be), title=tr(tv, te), explain=tr(ev, ee)) for ((tv, te, bv, be, ev, ee)) in [s[0] if isinstance(s[0], tuple) else s for s in part_['slides']] ]
        parts.append(dict(title=part_['title'], bullets=part_['bullets'], slides=slides))
    a5 = S.ripple_delay(5, 15)
    exs = [
      (('Ví dụ 1: bộ đếm gợn sóng 5 bit', 'Example 1: a 5-bit ripple counter'), ('5 flip-flop, mỗi cái trễ 15 ns: trễ tổng $5\\times15=75$ ns; $f_{max}\\approx1/75\\text{ ns}=13{,}3$ MHz; modulus $2^5=32$.', '5 flip-flops of 15 ns each: total delay $5\\times15=75$ ns; $f_{max}\\approx1/75\\text{ ns}=13.3$ MHz; modulus $2^5=32$.'), f'{a5} ns; {1 / (a5 * 1e-9) / 1e6:.2f} MHz'),
      (('Ví dụ 2: 555 một nhịp (Floyd)', 'Example 2: the 555 monostable (Floyd)'), ('$R_1=2{,}2$ kΩ, $C_1=0{,}01$ μF: $t_W=1{,}1\\times2200\\times10^{-8}=24{,}2$ μs.', '$R_1=2.2$ kΩ, $C_1=0.01$ μF: $t_W=1.1\\times2200\\times10^{-8}=24.2$ μs.'), f'{S.t555_mono(2200, 1e-8) * 1e6:.2f} μs'),
      (('Ví dụ 3: chuỗi bộ đếm Johnson 4 flip-flop', 'Example 3: the 4-flip-flop Johnson counter sequence'), ('Khởi đầu 0000, dịch phải với ngõ ra đảo nối về: ' + jt(4) + '. Modulus 8.', 'Starting at 0000, shifting right with the inverted output fed back: ' + jt(4) + '. Modulus 8.'), 'modulus 8'),
      (('Ví dụ 4: chuỗi bộ đếm 5, 8, 10, 10', 'Example 4: a chain of counters 5, 8, 10, 10'), ('Clock 10 MHz: $5\\times8\\times10\\times10=4000$ nên $f_{out}=10\\text{ MHz}/4000=2{,}5$ kHz (Floyd Self-Test 14).', '10 MHz clock: $5\\times8\\times10\\times10=4000$ so $f_{out}=10\\text{ MHz}/4000=2.5$ kHz (Floyd Self-Test 14).'), f'{float(S.freq_div(10e6, (5, 8, 10, 10))) / 1e3:g} kHz'),
      (('Ví dụ 5: chuỗi J-K', 'Example 5: a J-K sequence'), ('Q = 0; (J,K) = (1,0), (1,1), (0,0), (1,1): Q = 1, 0, 0, 1 (đặt, lật, giữ, lật).', 'Q = 0; (J,K) = (1,0), (1,1), (0,0), (1,1): Q = 1, 0, 0, 1 (set, toggle, hold, toggle).'), 'Q = 1, 0, 0, 1'),
    ]
    q = 0
    for (j, k) in ((1, 0), (1, 1), (0, 0), (1, 1)): q = S.jk(j, k, q)
    assert q == 1
    notes = '<h3>' + tr('Năm ví dụ có số', 'Five worked examples') + '</h3>' + ''.join(ex(tr(a, b), '<p>' + tr(c, d) + '</p><p><b>' + tr('Kết quả (kiểm bằng chương trình)', 'Result (checked by program)') + f':</b> {r}</p>') for (a, b), (c, d), r in exs)
    notes += callout('info', tr('Ánh xạ nguồn', 'Source mapping'), '<p>' + tr('Module không có slide của giảng viên. Floyd Chương 7 (PDF tr.388, chốt, flip-flop, one-shot, 555), Chương 8 (tr.450, thanh ghi dịch), Chương 9 (tr.498, bộ đếm), Chương 10 (tr.562, logic khả trình). Câu hỏi gốc là Đúng/Sai và Self-Test của bốn chương, khoá in ở trang 448, 495, 560, 626. Tooley 5.6 đến 5.8 (monostable, bistable, họ logic) đã nằm trong Module 02. Không có phần nào của Tooley hay slide nêu microcontroller.', 'The module has no lecturer slides. Floyd Chapter 7 (PDF p.388, latches, flip-flops, one-shot, 555), Chapter 8 (p.450, shift registers), Chapter 9 (p.498, counters), Chapter 10 (p.562, programmable logic). The original questions are the True/False and Self-Test items of the four chapters, with printed keys on pages 448, 495, 560, 626. Tooley 5.6 to 5.8 (monostable, bistable, logic families) is already in Module 02. Neither the lecturer slides nor Tooley mention microcontrollers here.') + '</p>')
    notes += callout('warn', tr('Khoá in của Floyd lệch so với chính văn bản (site dùng đáp án theo văn bản)', 'Floyd printed keys that disagree with the text (the site follows the text)'), ul([tr('Chương 9 Self-Test 2: khoá (a) "ngõ vào"; mục 9-1 nói ngõ ra Mealy phụ thuộc cả trạng thái hiện tại và ngõ vào, nên dùng (d).', 'Chapter 9 Self-Test 2: key (a) "inputs"; section 9-1 says a Mealy output depends on both the present state and the inputs, so (d) is used.'),
        tr('Chương 10 Đúng/Sai 7: khoá F cho "LAB có trong CPLD"; mục 10-2 định nghĩa LAB là khối của CPLD, nên đáp án là Đúng.', 'Chapter 10 True/False 7: key F for "LABs are found in CPLDs"; section 10-2 defines the LAB as the CPLD block, so the answer is True.'),
        tr('Chương 10 Self-Test 9: khoá (b) "cổng và thanh ghi dịch"; mục 10-2 mô tả macrocell gồm cổng, bộ dồn kênh và flip-flop, nên dùng (a).', 'Chapter 10 Self-Test 9: key (b) "gates and a shift register"; section 10-2 describes the macrocell as gates, multiplexers and a flip-flop, so (a) is used.'),
        tr('Chương 8 Self-Test 10 không được đưa vào ngân hàng vì cần Hình 8-36 chưa kiểm. Chương 10 Đúng/Sai 5 in nhầm "FGPA".', 'Chapter 8 Self-Test 10 is left out because it needs Figure 8-36, not yet checked. Chapter 10 True/False 5 misprints "FGPA".'),
        tr('Lớp chữ PDF của Chương 8 đọc micro giây (μs) thành "ms" ở Self-Test 5, 6, 9; ảnh trang cho thấy đơn vị đúng là μs.', 'The PDF text layer of Chapter 8 reads microseconds (μs) as "ms" in Self-Test 5, 6, 9; the page image shows the unit is μs.')]))
    return dict(subtitle=tr('Cách một mạch nhớ được trạng thái: chốt và flip-flop, mạch một nhịp và 555, thanh ghi dịch, bộ đếm và máy trạng thái, logic khả trình PAL, CPLD, FPGA. Dựng từ Floyd Chương 7 đến 10 (không có slide của giảng viên).',
                              'How a circuit remembers its state: latches and flip-flops, one-shots and the 555, shift registers, counters and state machines, programmable logic (PAL, CPLD, FPGA). Built from Floyd Chapters 7 to 10 (no lecturer slides).'),
                objectives_title=tr('Sau module này bạn sẽ', 'After this module you will'),
                objectives=[tr('phân biệt chốt và flip-flop kích sườn, viết bảng chân trị S-R, D, J-K, T', 'tell a latch from an edge-triggered flip-flop and write the S-R, D, J-K, T tables'),
                            tr('tính độ rộng xung của mạch một nhịp và tần số, chu kỳ làm việc của 555 dao động', 'compute the pulse width of a one-shot and the frequency and duty cycle of a 555 astable'),
                            tr('suy ra nội dung thanh ghi dịch, chuỗi bộ đếm vòng và Johnson, và thời gian trễ N/f', 'derive the contents of a shift register, the ring and Johnson sequences and the delay N/f'),
                            tr('xác định số flip-flop, modulus, tần số ra và trễ tích luỹ của bộ đếm gợn sóng, đồng bộ và mắc tầng', 'determine the flip-flops, modulus, output frequency and cumulative delay of ripple, synchronous and cascaded counters'),
                            tr('phân biệt PAL, GAL, CPLD, FPGA và mô tả luồng thiết kế và quét biên JTAG', 'tell PAL, GAL, CPLD and FPGA apart and describe the design flow and JTAG boundary scan')],
                parts=parts, notes=notes, notes_title=tr('Ghi chú chi tiết', 'Detailed notes'))
